import heapq


def fastest_delivery(n, roads, stations, capacity, swap_time, max_swaps, s, t):
    if s == t:
        return (0, 0)

    adj = [[] for _ in range(n)]
    for u, v, minutes, energy in roads:
        adj[u].append((v, minutes, energy))

    is_station = [False] * n
    for x in stations:
        if 0 <= x < n:
            is_station[x] = True

    C = capacity + 1
    K = max_swaps + 1
    INF = float('inf')
    # state index: (node * C + charge) * K + swaps_used
    dist = [INF] * (n * C * K)

    start = (s * C + capacity) * K
    dist[start] = 0
    # Heap key is (minutes, swaps, ...): this lexicographic cost never decreases
    # along a transition, so the first time t is popped the pair is optimal.
    heap = [(0, 0, capacity, s)]
    push = heapq.heappush
    pop = heapq.heappop

    while heap:
        d, k, c, u = pop(heap)
        if d > dist[(u * C + c) * K + k]:
            continue
        if u == t:
            return (d, k)

        # Swap (pointless when the battery is already full).
        if c < capacity and k < max_swaps and is_station[u]:
            nd = d + swap_time
            ni = (u * C + capacity) * K + k + 1
            if nd < dist[ni]:
                dist[ni] = nd
                push(heap, (nd, k + 1, capacity, u))

        # Drive.
        for v, minutes, energy in adj[u]:
            if energy > c:
                continue
            nc = c - energy
            if nc > capacity:
                nc = capacity
            nd = d + minutes
            ni = (v * C + nc) * K + k
            if nd < dist[ni]:
                dist[ni] = nd
                push(heap, (nd, k, nc, v))

    return None

def best_context(messages, budget, max_gap, bonus):
    if budget < 0 or max_gap < 0:
        raise ValueError("budget and max_gap must be non-negative")

    n = len(messages)
    if n == 0:
        return 0

    NEG = float("-inf")
    W = budget + 1

    # dp[i][b] = best score where message i is the LAST kept message so far
    #            and the kept messages have total length exactly b.
    dp = []
    last_pinned = -1  # index of the last pinned message strictly before i

    for i, (length, value, pinned) in enumerate(messages):
        if length > budget:
            row = [NEG] * W
        else:
            # Previous kept message j must satisfy:
            #   i - j - 1 <= max_gap, and no pinned message strictly between j and i.
            lo = max(0, i - 1 - max_gap, last_pinned)
            cands = dp[lo:i - 1] if i - 1 > lo else []
            if i >= 1:
                # adjacent predecessor earns the bonus
                cands = cands + [[x + bonus for x in dp[i - 1]]]

            if not cands:
                src = [NEG] * W
            elif len(cands) == 1:
                src = list(cands[0])
            else:
                src = list(map(max, *cands))

            # i may be the first kept message
            if last_pinned == -1 and i <= max_gap:
                if src[0] < 0:
                    src[0] = 0

            row = [NEG] * length + [x + value for x in src[:W - length]]

        dp.append(row)
        if pinned:
            last_pinned = i

    best = NEG

    # Empty set
    if last_pinned == -1 and n <= max_gap:
        best = 0

    # i as the last kept message: trailing dropped run <= max_gap, no pinned after i
    start = max(0, last_pinned, n - 1 - max_gap)
    for i in range(start, n):
        m = max(dp[i])
        if m > best:
            best = m

    if best == NEG:
        return None
    return int(best)

import heapq


def earliest_arrival(connections, transfer, source, target, start_time, max_boardings):
    if source == target:
        return start_time
    if max_boardings <= 0:
        return None

    n = len(transfer)
    INF = float('inf')

    # best[s]: minimal number of boardings with which the traveler can be
    # READY at station s at the current scan time (monotone non-increasing).
    best = [INF] * n
    # pending[s]: heap of (ready_time, boardings) events not yet applied to best[s]
    pending = [None] * n
    pending[source] = [(start_time, 0)]

    # trip_b[trip]: minimal number of boardings needed to be seated on the
    # most recently scanned connection of that trip.
    trip_b = {}

    ans = None
    heappush = heapq.heappush
    heappop = heapq.heappop

    # Scan by departure time. Since dep < arr, a connection can only depend on
    # connections with strictly smaller dep, so this is a valid topological order.
    for trip, u, v, dep, arr in sorted(connections, key=lambda c: c[3]):
        h = pending[u]
        if h:
            bu = best[u]
            while h and h[0][0] <= dep:
                b0 = heappop(h)[1]
                if b0 < bu:
                    bu = b0
            best[u] = bu
        else:
            bu = best[u]

        b = bu + 1                      # board here
        tb = trip_b.get(trip, INF)      # or stay seated from previous connection
        if tb < b:
            b = tb
        trip_b[trip] = b

        if b <= max_boardings:
            if v == target:
                if ans is None or arr < ans:
                    ans = arr
            if b < best[v]:
                hv = pending[v]
                if hv is None:
                    pending[v] = [(arr + transfer[v], b)]
                else:
                    heappush(hv, (arr + transfer[v], b))

    return ans

from collections import deque


def run_lock_manager(ops):
    BIG = 1 << 60
    log = []

    holders = {}      # res -> {tx: 'S' | 'X'}
    xhold = {}        # res -> tx holding X (if any)
    uq = {}           # res -> deque of queued upgrade requests (txs)
    nq = {}           # res -> deque of queued ordinary requests (txs)
    wh = {}           # res -> set of holders of res that are currently WAITING
    held = {}         # tx  -> set of resources it holds a lock on
    wres = {}         # waiting tx -> resource it waits on
    wmode = {}        # waiting tx -> requested mode
    wupg = {}         # waiting tx -> is upgrade request
    wkey = {}         # waiting tx -> ordering key inside its queue
    finished = set()

    def process_queue(R, i):
        h = holders[R]
        u = uq[R]
        n = nq[R]
        while True:
            if u:
                U = u[0]
                if len(h) != 1:          # other holders besides U
                    break
                u.popleft()
                h[U] = 'X'
                xhold[R] = U
                mode = 'X'
                hs = held[U]
                for Q in hs:
                    wh[Q].discard(U)
            elif n:
                U = n[0]
                mode = wmode[U]
                if mode == 'X':
                    if h:
                        break
                    xhold[R] = U
                elif R in xhold:
                    break
                n.popleft()
                h[U] = mode
                hs = held[U]
                for Q in hs:
                    wh[Q].discard(U)
                hs.add(R)
            else:
                break
            del wres[U]
            del wmode[U]
            del wupg[U]
            del wkey[U]
            log.append(("GRANT", i, U, R, mode))

    def release(T, i):
        hs = held[T]
        affected = set(hs)
        R0 = wres.pop(T, None)
        if R0 is not None:
            if wupg.pop(T):
                uq[R0].remove(T)
            else:
                nq[R0].remove(T)
            del wmode[T]
            del wkey[T]
            affected.add(R0)
        for Q in hs:
            del holders[Q][T]
            if xhold.get(Q) == T:
                del xhold[Q]
            wh[Q].discard(T)
        hs.clear()
        finished.add(T)
        for Q in sorted(affected):
            process_queue(Q, i)

    def find_victim(T):
        # T has just started waiting (or is still waiting after an abort);
        # every cycle in the wait-for graph passes through T.
        R = wres[T]
        kT = wkey[T]
        u = uq[R]
        front = u[0] if u else nq[R][0]

        # ---- forward search (resource level) ----
        # maxkey[Q] = largest queue key on Q reachable from T (prefix reached)
        maxkey = {R: kT}
        stack = [R]
        cyc = False
        while stack:
            Q = stack.pop()
            for V in wh[Q]:
                if V == T:
                    if Q != R or front != T:
                        cyc = True
                    continue
                Q2 = wres[V]
                k = wkey[V]
                mk = maxkey.get(Q2)
                if mk is None:
                    maxkey[Q2] = k
                    stack.append(Q2)
                elif k > mk:
                    maxkey[Q2] = k
        hiR = maxkey[R]
        if not cyc and hiR <= kT:
            return None

        # ---- backward search: nodes reachable from T that also reach T ----
        scc = {T}
        work = [T]
        if hiR > kT:
            for q in (uq[R], nq[R]):
                for U in q:
                    k = wkey[U]
                    if k > hiR:
                        break
                    if k > kT:
                        scc.add(U)
                        work.append(U)
        full = set()
        while work:
            X = work.pop()
            for Q in held[X]:
                if Q in full:
                    continue
                hi = maxkey.get(Q)
                if hi is None:
                    continue
                uu = uq[Q]
                nn = nq[Q]
                if uu:
                    f = uu[0]
                elif nn:
                    f = nn[0]
                else:
                    continue
                if f == X:
                    continue
                full.add(Q)
                for q in (uu, nn):
                    for U in q:
                        if wkey[U] > hi:
                            break
                        if U not in scc:
                            scc.add(U)
                            work.append(U)
        return max(scc)

    for i, op in enumerate(ops):
        kind = op[0]
        T = op[1]
        if T in finished or T in wres:
            log.append(("IGNORED", i, T))
            continue
        hs = held.get(T)
        if hs is None:
            hs = held[T] = set()
        if kind == "COMMIT":
            log.append(("COMMIT", i, T))
            release(T, i)
            continue

        R = op[2]
        h = holders.get(R)
        if h is None:
            h = holders[R] = {}
            uq[R] = deque()
            nq[R] = deque()
            wh[R] = set()

        cur = h.get(T)
        if cur is not None:
            if cur == 'X' or kind == 'S':
                log.append(("HELD", i, T, R))
                continue
            # upgrade
            if len(h) == 1:
                h[T] = 'X'
                xhold[R] = T
                log.append(("GRANT", i, T, R, "X"))
                continue
            uq[R].append(T)
            wupg[T] = True
            wkey[T] = i - BIG
        else:
            if (not uq[R] and not nq[R]
                    and (not h or (kind == 'S' and R not in xhold))):
                h[T] = kind
                if kind == 'X':
                    xhold[R] = T
                hs.add(R)
                log.append(("GRANT", i, T, R, kind))
                continue
            nq[R].append(T)
            wupg[T] = False
            wkey[T] = i

        wres[T] = R
        wmode[T] = kind
        for Q in hs:
            wh[Q].add(T)
        log.append(("WAIT", i, T, R, kind))

        # deadlock resolution: all cycles go through T
        while T in wres:
            victim = find_victim(T)
            if victim is None:
                break
            log.append(("ABORT", i, victim))
            release(victim, i)

    return log

def simulate_vending(prices, stock, bank, events, timeout):
    # Validate chronological order before producing anything.
    prev = None
    for ev in events:
        t = ev[0]
        if prev is not None and t < prev:
            raise ValueError("events are not in non-decreasing time order")
        prev = t

    accepted = (5, 10, 25, 100)
    denoms_desc = (100, 25, 10, 5)

    # Working copies (inputs are never mutated).
    bank_c = {5: 0, 10: 0, 25: 0, 100: 0}
    for k, v in bank.items():
        if k in bank_c:
            bank_c[k] = v
    stock_c = dict(stock)

    escrow = []          # coins of the current customer
    escrow_total = 0
    last = 0             # time of most recent activity
    log = []

    for ev in events:
        t, kind, arg = ev[0], ev[1], ev[2]

        # Automatic return that is due before this event.
        if escrow and t >= last + timeout:
            log.append(("TIMEOUT", last + timeout,
                        tuple(sorted(escrow, reverse=True))))
            escrow = []
            escrow_total = 0

        if kind == "coin":
            if arg not in accepted or len(escrow) >= 10:
                log.append(("REJECT", t, arg))
                # rejected coin is not an activity
            else:
                escrow.append(arg)
                escrow_total += arg
                last = t

        elif kind == "select":
            last = t
            if arg not in prices:
                log.append(("UNKNOWN", t, arg))
            elif stock_c[arg] == 0:
                log.append(("SOLD_OUT", t, arg))
            else:
                price = prices[arg]
                if escrow_total < price:
                    log.append(("NEED", t, price - escrow_total))
                else:
                    # Attempt the sale: escrow goes into the bank first.
                    snapshot = dict(bank_c)
                    for c in escrow:
                        bank_c[c] += 1
                    remaining = escrow_total - price
                    change = []
                    for d in denoms_desc:
                        if remaining <= 0:
                            break
                        k = min(bank_c[d], remaining // d)
                        if k > 0:
                            bank_c[d] -= k
                            remaining -= k * d
                            change.extend([d] * k)
                    if remaining == 0:
                        stock_c[arg] -= 1
                        escrow = []
                        escrow_total = 0
                        log.append(("VEND", t, arg, tuple(change)))
                    else:
                        bank_c = snapshot  # full rollback; escrow untouched
                        log.append(("EXACT_ONLY", t, arg))

        elif kind == "cancel":
            last = t
            if escrow:
                log.append(("RETURN", t, tuple(sorted(escrow, reverse=True))))
                escrow = []
                escrow_total = 0

        else:
            raise ValueError("unknown event kind: %r" % (kind,))

    # Pending automatic return after the last event.
    if escrow:
        log.append(("TIMEOUT", last + timeout,
                    tuple(sorted(escrow, reverse=True))))
        escrow = []
        escrow_total = 0

    final_bank = (bank_c[5], bank_c[10], bank_c[25], bank_c[100])
    return log, final_bank

import re

_NAME_RE = re.compile(r"[a-z0-9_]+")
_WORD_RE = re.compile(r"[a-z]+")
_PRINCIPAL_RE = re.compile(r"\*|(?:user|group):[a-z0-9_]+")
_ACTION_RE = re.compile(r"\*|[a-z]+(?:,[a-z]+)*")
_SEG_RE = re.compile(r"[a-z0-9._-]+")
_PATH_RE = re.compile(r"/|(?:/[a-z0-9._-]+)+")


def _valid_resource(resource):
    if resource == "/":
        return True
    if not resource.startswith("/"):
        return False
    for seg in resource[1:].split("/"):
        if seg == "*" or seg == "**":
            continue
        if not _SEG_RE.fullmatch(seg):
            return False
    return True


def _make_chunk(chunk):
    # (length, tuple of (offset, literal)) -- "*" positions need no check
    return (len(chunk), tuple((k, s) for k, s in enumerate(chunk) if s != "*"))


def _compile_resource(segs):
    if "**" not in segs:
        return (False, _make_chunk(segs))
    chunks = [[]]
    for s in segs:
        if s == "**":
            chunks.append([])
        else:
            chunks[-1].append(s)
    prefix = _make_chunk(chunks[0])
    suffix = _make_chunk(chunks[-1])
    middle = tuple(_make_chunk(c) for c in chunks[1:-1] if c)
    min_len = sum(len(c) for c in chunks)
    return (True, prefix, suffix, middle, min_len)


def _chunk_match(lits, segs, start):
    for off, lit in lits:
        if segs[start + off] != lit:
            return False
    return True


def _match(pat, segs):
    n = len(segs)
    if not pat[0]:
        length, lits = pat[1]
        return n == length and _chunk_match(lits, segs, 0)
    _, prefix, suffix, middle, min_len = pat
    if n < min_len:
        return False
    plen, plits = prefix
    slen, slits = suffix
    if not _chunk_match(plits, segs, 0):
        return False
    end = n - slen
    if not _chunk_match(slits, segs, end):
        return False
    pos = plen
    # greedy leftmost placement of each fixed-length middle chunk
    for clen, lits in middle:
        last = end - clen
        found = False
        while pos <= last:
            if _chunk_match(lits, segs, pos):
                found = True
                break
            pos += 1
        if not found:
            return False
        pos += clen
    return True


def evaluate_access(rules, requests) -> list:
    if not isinstance(rules, list):
        raise TypeError("rules must be a list")
    if not isinstance(requests, list):
        raise TypeError("requests must be a list")

    # ---- validate / compile rules ----
    res_ids = {}
    patterns = []
    by_spec = {}
    for i, rule in enumerate(rules):
        if not isinstance(rule, str):
            raise TypeError(f"rule {i}: not a str")
        fields = rule.split()
        if len(fields) != 4:
            raise ValueError(f"rule {i}: expected 4 fields, got {len(fields)}")
        effect, principal, action, resource = fields
        if effect != "ALLOW" and effect != "DENY":
            raise ValueError(f"rule {i}: bad effect {effect!r}")
        if not _PRINCIPAL_RE.fullmatch(principal):
            raise ValueError(f"rule {i}: bad principal {principal!r}")
        if not _ACTION_RE.fullmatch(action):
            raise ValueError(f"rule {i}: bad action {action!r}")
        if not _valid_resource(resource):
            raise ValueError(f"rule {i}: bad resource {resource!r}")

        if principal == "*":
            ptype, pname = 0, None
        elif principal.startswith("user:"):
            ptype, pname = 2, principal[5:]
        else:
            ptype, pname = 1, principal[6:]
        actions = None if action == "*" else frozenset(action.split(","))
        segs = [] if resource == "/" else resource[1:].split("/")
        literal_count = sum(1 for s in segs if s != "*" and s != "**")
        spec = (literal_count, ptype, 0 if actions is None else 1)
        rid = res_ids.get(resource)
        if rid is None:
            rid = len(patterns)
            res_ids[resource] = rid
            patterns.append(_compile_resource(segs))
        by_spec.setdefault(spec, []).append(
            (i, effect == "DENY", ptype, pname, actions, rid)
        )

    # ---- validate requests ----
    for j, req in enumerate(requests):
        if not isinstance(req, tuple) or len(req) != 4:
            raise TypeError(f"request {j}: expected 4-tuple")
        user, groups, action, path = req
        if not isinstance(user, str) or not _NAME_RE.fullmatch(user):
            raise ValueError(f"request {j}: bad user {user!r}")
        if not isinstance(groups, list):
            raise ValueError(f"request {j}: bad groups")
        for g in groups:
            if not isinstance(g, str) or not _NAME_RE.fullmatch(g):
                raise ValueError(f"request {j}: bad groups")
        if not isinstance(action, str) or not _WORD_RE.fullmatch(action):
            raise ValueError(f"request {j}: bad action {action!r}")
        if not isinstance(path, str) or not _PATH_RE.fullmatch(path):
            raise ValueError(f"request {j}: bad path {path!r}")

    # ---- evaluation ----
    # rule groups from most to least specific; inside a group rules are in index order
    spec_groups = [by_spec[s] for s in sorted(by_spec, reverse=True)]
    nres = len(patterns)
    path_cache = {}      # path -> (segments, bytearray memo per resource id)
    decision_cache = {}
    out = []

    for user, groups, action, path in requests:
        gset = frozenset(groups)
        key = (user, gset, action, path)
        decision = decision_cache.get(key)
        if decision is not None:
            out.append(decision)
            continue

        entry = path_cache.get(path)
        if entry is None:
            segs = [] if path == "/" else path[1:].split("/")
            entry = (segs, bytearray(nres))
            path_cache[path] = entry
        segs, memo = entry

        decision = "DENY by default"
        for group in spec_groups:
            allow = -1
            deny = -1
            for idx, is_deny, ptype, pname, actions, rid in group:
                if allow >= 0 and not is_deny:
                    continue  # already have a smaller-index ALLOW
                if ptype == 2:
                    if pname != user:
                        continue
                elif ptype == 1:
                    if pname not in gset:
                        continue
                if actions is not None and action not in actions:
                    continue
                c = memo[rid]
                if c == 0:
                    c = 1 if _match(patterns[rid], segs) else 2
                    memo[rid] = c
                if c == 2:
                    continue
                if is_deny:
                    deny = idx
                    break  # first DENY in index order is the smallest
                allow = idx
            if deny >= 0:
                decision = f"DENY by rule {deny}"
                break
            if allow >= 0:
                decision = f"ALLOW by rule {allow}"
                break

        decision_cache[key] = decision
        out.append(decision)

    return out

import copy
import json
import re

_IDENT_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")


def _type_name(v):
    if v is None:
        return "null"
    if isinstance(v, bool):          # must be tested before int
        return "bool"
    if isinstance(v, dict):
        return "dict"
    if isinstance(v, list):
        return "list"
    if isinstance(v, str):
        return "str"
    if isinstance(v, int):
        return "int"
    if isinstance(v, float):
        return "float"
    return type(v).__name__          # not JSON-like; best effort


def _copy(v):
    """Deep copy of a JSON-like value (dicts/lists are always fresh objects)."""
    if isinstance(v, dict):
        return {k: _copy(x) for k, x in v.items()}
    if isinstance(v, list):
        return [_copy(x) for x in v]
    if v is None or isinstance(v, (str, int, float, bool)):
        return v
    return copy.deepcopy(v)


def _child_path(parent, name):
    if _IDENT_RE.fullmatch(name):
        return parent + "." + name
    return parent + "[" + json.dumps(name, ensure_ascii=False) + "]"


def _merge(target, overlay, path, layer, warnings):
    for key, value in overlay.items():
        # 1. key must be a string
        if not isinstance(key, str):
            raise TypeError(f"layer {layer}: non-string key at {path}")

        # 2. classify
        if key.startswith("-"):
            kind, name = "delete", key[1:]
        elif key.endswith("+"):
            kind, name = "append", key[:-1]
        else:
            kind, name = "set", key

        # 3. empty name
        if name == "":
            raise ValueError(f"layer {layer}: empty key name at {path}")

        # 4. apply
        q = _child_path(path, name)

        if kind == "delete":
            if value is not None:
                raise ValueError(
                    f"layer {layer}: delete directive needs null at {q}")
            if name in target:
                del target[name]
            else:
                warnings.append(f"layer {layer}: delete of missing key at {q}")

        elif kind == "append":
            if not isinstance(value, list):
                raise ValueError(
                    f"layer {layer}: append directive needs a list at {q}")
            if name not in target:
                target[name] = _copy(value)
            elif isinstance(target[name], list):
                target[name].extend(_copy(x) for x in value)
            else:
                raise ValueError(
                    f"layer {layer}: cannot append to "
                    f"{_type_name(target[name])} at {q}")

        else:  # plain set
            if name in target:
                old_t = _type_name(target[name])
                new_t = _type_name(value)
                if old_t != new_t:
                    warnings.append(
                        f"layer {layer}: type change at {q}: {old_t} -> {new_t}")

            if isinstance(value, dict):
                existing = target.get(name)
                if not (name in target and isinstance(existing, dict)):
                    existing = {}
                    target[name] = existing   # keeps position if key existed
                _merge(existing, value, q, layer, warnings)
            else:
                target[name] = _copy(value)   # keeps position if key existed


def merge_layers(layers) -> tuple[dict, list[str]]:
    if not isinstance(layers, list):
        raise TypeError("layers must be a list")

    result: dict = {}
    warnings: list[str] = []

    for index, layer in enumerate(layers):
        if not isinstance(layer, dict):
            raise TypeError(f"layer {index} is not a dict")
        _merge(result, layer, "$", index, warnings)

    return result, warnings

import re

_OPENING_RE = re.compile(r"-?(0|[1-9][0-9]{0,8})\.[0-9]{2}")
_AMOUNT_RE = re.compile(r"(0|[1-9][0-9]{0,8})(\.[0-9]{1,2})?")
_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")

_KINDS = ("credit", "debit", "fee")
_OVERDRAFT_FEE_CENTS = 2500
_OVERDRAFT_MEMO = "OVERDRAFT FEE"


def _valid_date(s):
    if not isinstance(s, str) or _DATE_RE.fullmatch(s) is None:
        return False
    year, month, day = int(s[0:4]), int(s[5:7]), int(s[8:10])
    if year < 1900 or year > 2999:
        return False
    if month < 1 or month > 12:
        return False
    if month == 2:
        leap = (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)
        dim = 29 if leap else 28
    elif month in (4, 6, 9, 11):
        dim = 30
    else:
        dim = 31
    return 1 <= day <= dim


def _amount_to_cents(s):
    """Parse an unsigned amount string (already validated) into integer cents."""
    if "." in s:
        whole, frac = s.split(".")
        frac = (frac + "0")[:2]
    else:
        whole, frac = s, "00"
    return int(whole) * 100 + int(frac)


def _money(cents):
    sign = "-" if cents < 0 else ""
    a = abs(cents)
    return "%s%s.%02d" % (sign, format(a // 100, ","), a % 100)


def _format_memo(memo):
    m = " ".join(memo.split())
    if len(m) > 20:
        m = m[:19] + "~"
    return m.ljust(20)


def render_statement(opening, entries) -> list[str]:
    # ---------- validation (complete before any output) ----------
    if not isinstance(opening, str):
        raise TypeError("opening must be a str")
    if _OPENING_RE.fullmatch(opening) is None:
        raise ValueError("opening: bad amount " + repr(opening))
    if not isinstance(entries, list):
        raise TypeError("entries must be a list")

    parsed = []  # (date, kind, cents, memo)
    prev_date = None
    for i, entry in enumerate(entries):
        if not isinstance(entry, tuple) or len(entry) != 4:
            raise TypeError(f"entry {i}: expected 4-tuple")
        date, kind, amount, memo = entry

        if not _valid_date(date):
            raise ValueError(f"entry {i}: bad date {date!r}")

        # ISO dates of identical fixed format compare correctly as strings
        if prev_date is not None and date < prev_date:
            raise ValueError(f"entry {i}: date out of order")

        if not isinstance(kind, str) or kind not in _KINDS:
            raise ValueError(f"entry {i}: bad kind {kind!r}")

        if not isinstance(amount, str) or _AMOUNT_RE.fullmatch(amount) is None:
            raise ValueError(f"entry {i}: bad amount {amount!r}")
        cents = _amount_to_cents(amount)
        if cents == 0:
            raise ValueError(f"entry {i}: bad amount {amount!r}")

        if (
            not isinstance(memo, str)
            or not memo.split()
            or any(ord(ch) < 32 or ord(ch) == 127 for ch in memo)
        ):
            raise ValueError(f"entry {i}: bad memo")

        parsed.append((date, kind, cents, memo))
        prev_date = date

    # ---------- processing ----------
    negative = opening.startswith("-")
    balance = _amount_to_cents(opening[1:] if negative else opening)
    if negative:
        balance = -balance

    lines = ["Opening balance: " + _money(balance)]
    counts = {"credit": 0, "debit": 0, "fee": 0}
    auto_fee_dates = set()

    def apply(date, kind, cents, memo):
        nonlocal balance
        if kind == "credit":
            balance += cents
            sign = "+"
        else:
            balance -= cents
            sign = "-"
        counts[kind] += 1
        amt = (sign + _money(cents)).rjust(14)
        bal = _money(balance).rjust(15)
        flag = " OD" if balance < 0 else ""
        lines.append(f"{date}  {_format_memo(memo)}  {amt}  {bal}{flag}")

    for date, kind, cents, memo in parsed:
        apply(date, kind, cents, memo)
        if kind == "debit" and balance < 0 and date not in auto_fee_dates:
            auto_fee_dates.add(date)
            apply(date, "fee", _OVERDRAFT_FEE_CENTS, _OVERDRAFT_MEMO)

    lines.append("Closing balance: " + _money(balance))
    lines.append(
        f"Credits: {counts['credit']}  Debits: {counts['debit']}  Fees: {counts['fee']}"
    )
    return lines

import re

_NUM = r"(?:0|[1-9][0-9]*)"
_VER = rf"({_NUM})\.({_NUM})\.({_NUM})(?:~rc([1-9][0-9]*))?"

_VERSION_RE = re.compile(_VER)
_CMP_RE = re.compile(rf"(!=|>=|<=|=|>|<)?{_VER}")
_MAJOR_RE = re.compile(rf"({_NUM})\.\*")
_MAJOR_MINOR_RE = re.compile(rf"({_NUM})\.({_NUM})\.\*")
_AT_RE = re.compile(rf"@({_NUM})\.({_NUM})")


def _num_key(digits):
    # Canonical (no leading zeros, ASCII) digit strings compare numerically
    # as (length, text); this avoids int() and its size limits.
    return (len(digits), digits)


def _version_key(x, y, z, rc):
    # Release candidates sort below the plain release of the same X.Y.Z.
    tail = (1, (0, "")) if rc is None else (0, _num_key(rc))
    return (_num_key(x), _num_key(y), _num_key(z), tail)


def _parse_version(text):
    m = _VERSION_RE.fullmatch(text)
    if m is None:
        return None
    return _version_key(*m.groups())


def _is_rc(key):
    return key[3][0] == 0


def _compile_clause(clause):
    """Return a predicate over version keys, or None if the clause is invalid."""
    if clause == "*":
        return lambda k: True

    m = _MAJOR_RE.fullmatch(clause)
    if m:
        major = _num_key(m.group(1))
        return lambda k: k[0] == major

    m = _MAJOR_MINOR_RE.fullmatch(clause)
    if m:
        major = _num_key(m.group(1))
        minor = _num_key(m.group(2))
        return lambda k: k[0] == major and k[1] == minor

    m = _AT_RE.fullmatch(clause)
    if m:
        major = _num_key(m.group(1))
        minor = _num_key(m.group(2))
        return lambda k: k[0] == major and k[1] >= minor

    m = _CMP_RE.fullmatch(clause)
    if m:
        op = m.group(1) or "="
        ref = _version_key(m.group(2), m.group(3), m.group(4), m.group(5))
        if op == "=":
            return lambda k: k == ref
        if op == "!=":
            return lambda k: k != ref
        if op == ">":
            return lambda k: k > ref
        if op == ">=":
            return lambda k: k >= ref
        if op == "<":
            return lambda k: k < ref
        return lambda k: k <= ref  # "<="

    return None


def pick_version(available, constraint):
    # 1. available must be a list
    if not isinstance(available, list):
        raise TypeError("available must be a list")

    # 2. every element must be a valid version string
    versions = []
    for i, element in enumerate(available):
        key = _parse_version(element) if isinstance(element, str) else None
        if key is None:
            raise ValueError(f"invalid version at index {i}: {element!r}")
        versions.append((key, element))

    # 3. constraint must be a str
    if not isinstance(constraint, str):
        raise TypeError("constraint must be a str")

    # 4. constraint must not be empty / only spaces
    if constraint.strip(" ") == "":
        raise ValueError("empty constraint")

    # 5. parse and validate all alternatives and clauses
    alternatives = []
    for a, alt in enumerate(constraint.split("|"), start=1):
        alt = alt.strip(" ")
        allow_rc = False
        if alt.startswith("?"):
            allow_rc = True
            alt = alt[1:].strip(" ")
        if alt == "":
            raise ValueError(f"alternative {a} is empty")

        predicates = []
        for c, clause in enumerate(alt.split(","), start=1):
            clause = clause.strip(" ")
            pred = _compile_clause(clause)
            if pred is None:
                raise ValueError(
                    f"alternative {a}, clause {c}: invalid clause {clause!r}"
                )
            predicates.append(pred)
        alternatives.append((allow_rc, predicates))

    # Matching (only after validation is complete)
    best_key = None
    best_str = None
    for key, text in versions:
        if best_key is not None and key <= best_key:
            continue
        rc = _is_rc(key)
        for allow_rc, predicates in alternatives:
            if rc and not allow_rc:
                continue
            if all(pred(key) for pred in predicates):
                best_key, best_str = key, text
                break

    return best_str

import re

_KEY_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_-]*")
_INT_RE = re.compile(r"-?(?:0|[1-9][0-9]*)")
_SPECIAL_RE = re.compile(r'[\\"]')
_ESCAPES = {"\\": "\\", '"': '"', "n": "\n", "t": "\t"}


def _digits_to_int(s):
    # Avoids Python's int<->str digit limit (ValueError on very long literals).
    if len(s) <= 4000:
        return int(s)
    half = len(s) // 2
    return _digits_to_int(s[:-half]) * (10 ** half) + _digits_to_int(s[-half:])


def _scalar(t):
    """Return (error_message_or_None, value)."""
    if t[0] == '"':
        n = len(t)
        i = 1
        parts = []
        while True:
            m = _SPECIAL_RE.search(t, i)
            if m is None:
                return "bad string", None
            j = m.start()
            if j > i:
                parts.append(t[i:j])
            if t[j] == '"':
                if j != n - 1:
                    return "bad string", None
                return None, "".join(parts)
            # backslash
            if j + 1 >= n:
                return "bad escape", None
            rep = _ESCAPES.get(t[j + 1])
            if rep is None:
                return "bad escape", None
            parts.append(rep)
            i = j + 2
    if t == "true":
        return None, True
    if t == "false":
        return None, False
    if t == "null":
        return None, None
    if _INT_RE.fullmatch(t):
        if t[0] == "-":
            return None, -_digits_to_int(t[1:])
        return None, _digits_to_int(t)
    return None, t


def parse_outline(text: str) -> tuple:
    root = None
    started = False
    indents = []      # indentation of each open block
    conts = []        # container (dict or list) of each open block
    opener = None     # (container, key_or_index, indent) of previous opener line

    lineno = 0
    for line in text.split("\n"):
        lineno += 1
        rest = line.lstrip(" \t")
        if not rest or rest[0] == "#":
            continue
        indent = len(line) - len(rest)

        # 1. tab in indentation
        if line.find("\t", 0, indent) != -1:
            return ("error", lineno, "tab in indentation")

        # 2/3. entry syntax
        key = None
        if rest == "-" or rest.startswith("- "):
            is_item = True
            t = rest[2:].strip(" ")
        else:
            is_item = False
            pos = rest.find(":")
            if pos < 0:
                return ("error", lineno, "invalid entry")
            key = rest[:pos]
            if _KEY_RE.fullmatch(key) is None:
                return ("error", lineno, "invalid entry")
            after = rest[pos + 1:]
            t = after.strip(" ")
            if t and after[0] != " ":
                return ("error", lineno, "invalid entry")

        # 4. scalar conversion
        is_opener = not t
        if is_opener:
            value = None
        else:
            err, value = _scalar(t)
            if err is not None:
                return ("error", lineno, err)

        # structure
        if not started:
            if indent != 0:
                return ("error", lineno, "unexpected indent")
            started = True
            cont = [] if is_item else {}
            root = cont
            indents.append(0)
            conts.append(cont)
        elif opener is not None and indent > opener[2]:
            cont = [] if is_item else {}
            opener[0][opener[1]] = cont
            indents.append(indent)
            conts.append(cont)
        else:
            top = indents[-1]
            if indent > top:
                return ("error", lineno, "unexpected indent")
            if indent < top:
                while indents[-1] > indent:
                    indents.pop()
                    conts.pop()
                if indents[-1] != indent:
                    return ("error", lineno, "inconsistent dedent")
            cont = conts[-1]
            if isinstance(cont, list) != is_item:
                return ("error", lineno, "mixed block")
            if not is_item and key in cont:
                return ("error", lineno, "duplicate key '%s'" % key)

        # add the entry
        if is_item:
            cont.append(value)
            opener = (cont, len(cont) - 1, indent) if is_opener else None
        else:
            cont[key] = value
            opener = (cont, key, indent) if is_opener else None

    return ("ok", root)

import re

_TOKEN_RE = re.compile(r'[\[\]]|[^ \t\n\r\[\]]+')
_INT_RE = re.compile(r'-?[0-9]+')

# opcodes: 0 = end of sequence ("]", ";", end of program), 1 = push literal,
# 2 = user word, 3.. = builtins, 20 = definition.  Negative = structural tokens.
_KINDS = {
    'dup': 3, 'drop': 4, 'swap': 5, 'over': 6, 'rot': 7,
    '+': 8, '-': 9, '*': 10, '<': 11, '=': 12, '/': 13, '%': 14,
    'if': 15, 'call': 16, 'times': 17, 'while': 18, 'dip': 19,
    '[': -1, ']': -2, ':': -3, ';': -4,
}


def _to_int(t):
    try:
        return int(t)
    except ValueError:            # very long literal (int-str digit limit)
        neg = t[0] == '-'
        digits = t[1:] if neg else t
        v = 0
        for k in range(0, len(digits), 4000):
            chunk = digits[k:k + 4000]
            v = v * 10 ** len(chunk) + int(chunk)
        return -v if neg else v


def run_pile(src: str, max_steps: int) -> tuple:
    toks = _TOKEN_RE.findall(src)
    n = len(toks)

    # ---------------- structure check + compilation (one pass) -------------
    ops = [0] * (n + 1)            # ops[n] is the end-of-program sentinel
    val = [None] * (n + 1)         # int value / quotation value / word id
    nxt = list(range(1, n + 2))    # index of the element following this one
    wids = {}                      # user word name -> id
    qopen = []                     # indexes of open "["
    dopen = -1                     # index of the open ":" (or -1)
    kinds_get = _KINDS.get
    int_match = _INT_RE.fullmatch

    i = 0
    while i < n:
        t = toks[i]
        k = kinds_get(t)
        if k is None:
            if int_match(t):
                ops[i] = 1
                val[i] = _to_int(t)
            else:
                w = wids.get(t)
                if w is None:
                    w = wids[t] = len(wids)
                ops[i] = 2
                val[i] = w
        elif k > 0:
            ops[i] = k
        elif k == -1:
            qopen.append(i)
        elif k == -2:
            if not qopen:
                return ("error", i, "unmatched ]")
            j = qopen.pop()
            ops[j] = 1
            val[j] = (j + 1,)      # quotation value: (index of first body token,)
            nxt[j] = i + 1
        elif k == -3:
            if qopen or dopen >= 0:
                return ("error", i, "misplaced :")
            if i == n - 1:
                return ("error", i, "unclosed :")
            name = toks[i + 1]
            if name in _KINDS or int_match(name):
                return ("error", i + 1, "bad name")
            w = wids.get(name)
            if w is None:
                w = wids[name] = len(wids)
            ops[i] = 20
            val[i] = w
            dopen = i
            i += 1                 # the NAME is consumed here
        else:
            if qopen or dopen < 0:
                return ("error", i, "unmatched ;")
            nxt[dopen] = i + 1
            dopen = -1
        i += 1

    if dopen >= 0:
        return ("error", dopen, "unclosed :")
    if qopen:
        return ("error", qopen[0], "unclosed [")

    # ------------------------------ execution ------------------------------
    wdef = [-1] * len(wids)        # word id -> index of first body token
    stack = []
    rstack = [None]                # return stack; None = bottom marker
    push = stack.append
    pop = stack.pop
    rpush = rstack.append
    rpop = rstack.pop
    budget = max_steps
    ip = 0

    try:
        while True:
            op = ops[ip]
            if op:
                if budget <= 0:
                    return ("error", ip, "step limit exceeded")
                budget -= 1
                if op < 8:
                    if op == 1:                     # int / quotation literal
                        push(val[ip])
                        ip = nxt[ip]
                    elif op == 2:                   # user word
                        b = wdef[val[ip]]
                        if b < 0:
                            return ("error", ip,
                                    "unknown word '" + toks[ip] + "'")
                        rpush(ip + 1)
                        ip = b
                    elif op == 3:                   # dup
                        push(stack[-1])
                        ip += 1
                    elif op == 4:                   # drop
                        pop()
                        ip += 1
                    elif op == 5:                   # swap
                        stack[-1], stack[-2] = stack[-2], stack[-1]
                        ip += 1
                    elif op == 6:                   # over
                        push(stack[-2])
                        ip += 1
                    else:                           # rot
                        push(pop(-3))
                        ip += 1
                elif op < 15:                       # binary int operators
                    b = pop()
                    a = stack[-1]
                    if type(a) is not int or type(b) is not int:
                        return ("error", ip, "type error")
                    if op == 8:
                        stack[-1] = a + b
                    elif op == 9:
                        stack[-1] = a - b
                    elif op == 10:
                        stack[-1] = a * b
                    elif op == 11:
                        stack[-1] = 1 if a < b else 0
                    elif op == 12:
                        stack[-1] = 1 if a == b else 0
                    else:
                        if b == 0:
                            return ("error", ip, "division by zero")
                        stack[-1] = a // b if op == 13 else a % b
                    ip += 1
                elif op == 15:                      # if
                    f = pop()
                    t = pop()
                    c = pop()
                    if type(c) is not int or type(t) is int or type(f) is int:
                        return ("error", ip, "type error")
                    rpush(ip + 1)
                    ip = t[0] if c else f[0]
                elif op == 16:                      # call
                    q = pop()
                    if type(q) is int:
                        return ("error", ip, "type error")
                    rpush(ip + 1)
                    ip = q[0]
                elif op == 17:                      # times
                    cnt = pop()
                    q = pop()
                    if type(q) is int or type(cnt) is not int:
                        return ("error", ip, "type error")
                    if cnt < 0:
                        return ("error", ip, "negative count")
                    s = q[0]
                    if cnt and ops[s]:              # skip empty quotations
                        rpush([2, ip + 1, s, cnt - 1])
                        ip = s
                    else:
                        ip += 1
                elif op == 18:                      # while
                    b = pop()
                    c = pop()
                    if type(b) is int or type(c) is int:
                        return ("error", ip, "type error")
                    rpush([3, ip, c[0], b[0]])
                    ip = c[0]
                elif op == 19:                      # dip
                    q = pop()
                    a = pop()
                    if type(q) is int:
                        return ("error", ip, "type error")
                    rpush((1, ip + 1, a))
                    ip = q[0]
                else:                               # definition
                    wdef[val[ip]] = ip + 2
                    ip = nxt[ip]
            else:
                # end of the current sequence: resume whatever is waiting
                fr = rpop()
                if type(fr) is int:
                    ip = fr
                elif fr is None:
                    break
                else:
                    k = fr[0]
                    if k == 1:                      # dip: restore value
                        push(fr[2])
                        ip = fr[1]
                    elif k == 2:                    # times: next iteration
                        r = fr[3]
                        if r:
                            fr[3] = r - 1
                            rpush(fr)
                            ip = fr[2]
                        else:
                            ip = fr[1]
                    elif k == 3:                    # while: condition done
                        if not stack:
                            return ("error", fr[1], "stack underflow")
                        v = pop()
                        if type(v) is not int:
                            return ("error", fr[1], "type error")
                        if v:
                            fr[0] = 4
                            rpush(fr)
                            ip = fr[3]
                        else:
                            ip = fr[1] + 1
                    else:                           # while: body done
                        fr[0] = 3
                        rpush(fr)
                        ip = fr[2]
    except IndexError:
        # only data-stack accesses of the builtin at `ip` can raise this
        return ("error", ip, "stack underflow")

    # ------------------------------- result --------------------------------
    memo = {}                      # body start -> list (built once, iteratively)
    out = []
    for v in stack:
        if type(v) is int:
            out.append(v)
            continue
        s = v[0]
        lst = memo.get(s)
        if lst is None:
            lst = memo[s] = []
            cur = lst
            parents = []
            i = s
            while True:
                t = toks[i]
                if t == '[':
                    m = memo.get(i + 1)
                    if m is not None:
                        cur.append(m)
                        i = nxt[i]
                        continue
                    new = memo[i + 1] = []
                    cur.append(new)
                    parents.append(cur)
                    cur = new
                elif t == ']':
                    if not parents:
                        break
                    cur = parents.pop()
                else:
                    cur.append(t)
                i += 1
        out.append(lst)
    return ("ok", out)

import operator

_CMP_FUNCS = {
    '=': operator.eq,
    '!=': operator.ne,
    '<': operator.lt,
    '<=': operator.le,
    '>': operator.gt,
    '>=': operator.ge,
}

_KEYWORDS = ('and', 'or', 'not', 'in', 'has')


def _parse_int(text):
    # Avoids Python's limit on int<->str conversion for very long digit runs.
    neg = text.startswith('-')
    digits = text[1:] if neg else text
    if len(digits) <= 4000:
        val = int(digits)
    else:
        val = 0
        step = 4000
        for s in range(0, len(digits), step):
            chunk = digits[s:s + step]
            val = val * (10 ** len(chunk)) + int(chunk)
    return -val if neg else val


def filter_records(query: str, records: list) -> tuple:
    n = len(query)

    # ---------------- STEP 1: lexing ----------------
    tokens = []  # (type, value, pos, text)
    i = 0
    while i < n:
        c = query[i]
        if c == ' ' or c == '\t' or c == '\n':
            i += 1
            continue
        if c in '()[],':
            tokens.append((c, None, i, c))
            i += 1
            continue
        if c in '!<>=':
            if c != '=' and i + 1 < n and query[i + 1] == '=':
                op = c + '='
                tokens.append(('CMP', op, i, op))
                i += 2
                continue
            if c == '!':
                return ("error", i, "unexpected character '!'")
            tokens.append(('CMP', c, i, c))
            i += 1
            continue
        if c == '-' or '0' <= c <= '9':
            j = i
            if c == '-':
                j += 1
                if j >= n or not ('0' <= query[j] <= '9'):
                    return ("error", i, "unexpected character '-'")
            while j < n and '0' <= query[j] <= '9':
                j += 1
            text = query[i:j]
            tokens.append(('INT', _parse_int(text), i, text))
            i = j
            continue
        if c == '"':
            j = i + 1
            parts = []
            closed = False
            while j < n:
                ch = query[j]
                if ch == '"':
                    closed = True
                    break
                if ch == '\\':
                    if j + 1 < n and (query[j + 1] == '"' or query[j + 1] == '\\'):
                        parts.append(query[j + 1])
                        j += 2
                        continue
                    return ("error", j, "bad escape")
                parts.append(ch)
                j += 1
            if not closed:
                return ("error", i, "unterminated string")
            tokens.append(('STR', ''.join(parts), i, query[i:j + 1]))
            i = j + 1
            continue
        if ('a' <= c <= 'z') or ('A' <= c <= 'Z') or c == '_':
            j = i + 1
            while j < n:
                ch = query[j]
                if (('a' <= ch <= 'z') or ('A' <= ch <= 'Z') or
                        ('0' <= ch <= '9') or ch == '_' or ch == '.'):
                    j += 1
                else:
                    break
            w = query[i:j]
            if w in _KEYWORDS:
                tokens.append((w, None, i, w))
            else:
                tokens.append(('FIELD', w, i, w))
            i = j
            continue
        return ("error", i, "unexpected character '%s'" % c)
    tokens.append(('END', None, n, ''))

    def err(tok):
        if tok[0] == 'END':
            return ("error", tok[2], "unexpected end of input")
        return ("error", tok[2], "unexpected token '%s'" % tok[3])

    # ---------------- STEP 2: parsing (iterative, to postfix) ----------------
    # instruction codes: 0 cmp, 1 in, 2 has, 3 not, 4 and, 5 or
    NOT, AND, OR, LP = 3, 4, 5, 9
    prog = []
    ops = []
    k = 0
    expect_operand = True
    while True:
        t = tokens[k]
        tt = t[0]
        if expect_operand:
            if tt == 'not':
                ops.append(NOT)
                k += 1
            elif tt == '(':
                ops.append(LP)
                k += 1
            elif tt == 'has':
                t2 = tokens[k + 1]
                if t2[0] != 'FIELD':
                    return err(t2)
                prog.append((2, t2[1]))
                k += 2
                expect_operand = False
            elif tt == 'FIELD':
                t2 = tokens[k + 1]
                if t2[0] == 'CMP':
                    t3 = tokens[k + 2]
                    if t3[0] != 'INT' and t3[0] != 'STR':
                        return err(t3)
                    op = t2[1]
                    if op == '=':
                        mism = 0
                    elif op == '!=':
                        mism = 2
                    else:
                        mism = 1
                    prog.append((0, t[1], _CMP_FUNCS[op], t3[1],
                                 t3[0] == 'STR', mism))
                    k += 3
                    expect_operand = False
                elif t2[0] == 'in':
                    t3 = tokens[k + 2]
                    if t3[0] != '[':
                        return err(t3)
                    k += 3
                    int_set = set()
                    str_set = set()
                    while True:
                        lt = tokens[k]
                        if lt[0] == 'INT':
                            int_set.add(lt[1])
                        elif lt[0] == 'STR':
                            str_set.add(lt[1])
                        else:
                            return err(lt)
                        k += 1
                        sep = tokens[k]
                        if sep[0] == ',':
                            k += 1
                        elif sep[0] == ']':
                            k += 1
                            break
                        else:
                            return err(sep)
                    prog.append((1, t[1], int_set, str_set))
                    expect_operand = False
                else:
                    return err(t2)
            else:
                return err(t)
        else:
            if tt == 'and':
                while ops and (ops[-1] == NOT or ops[-1] == AND):
                    prog.append((ops.pop(),))
                ops.append(AND)
                k += 1
                expect_operand = True
            elif tt == 'or':
                while ops and ops[-1] != LP:
                    prog.append((ops.pop(),))
                ops.append(OR)
                k += 1
                expect_operand = True
            elif tt == ')':
                while ops and ops[-1] != LP:
                    prog.append((ops.pop(),))
                if not ops:
                    return err(t)
                ops.pop()
                k += 1
            elif tt == 'END':
                while ops:
                    o = ops.pop()
                    if o == LP:
                        return err(t)
                    prog.append((o,))
                break
            else:
                return err(t)

    # ---------------- STEP 3: evaluation ----------------
    # truth encoding: FALSE = 0, UNKNOWN = 1, TRUE = 2
    result = []
    for idx, rec in enumerate(records):
        st = []
        push = st.append
        pop = st.pop
        for ins in prog:
            code = ins[0]
            if code == 0:
                f = ins[1]
                if f in rec:
                    v = rec[f]
                    if isinstance(v, str) != ins[4]:
                        push(ins[5])
                    else:
                        push(2 if ins[2](v, ins[3]) else 0)
                else:
                    push(1)
            elif code == 4:
                b = pop()
                if b < st[-1]:
                    st[-1] = b
            elif code == 5:
                b = pop()
                if b > st[-1]:
                    st[-1] = b
            elif code == 3:
                st[-1] = 2 - st[-1]
            elif code == 1:
                f = ins[1]
                if f in rec:
                    v = rec[f]
                    if isinstance(v, str):
                        push(2 if v in ins[3] else 0)
                    else:
                        push(2 if v in ins[2] else 0)
                else:
                    push(1)
            else:  # has
                push(2 if ins[1] in rec else 0)
        if st[-1] == 2:
            result.append(idx)
    return ("ok", result)

import re

_TOKEN_RE = re.compile(
    r"( +)|([0-9]+)|([a-z_][a-z0-9_]*)|(<=|>=|==|!=|[-+*/%^()?:<>])|(.)",
    re.DOTALL,
)

# opcodes
(_PUSH, _LOAD, _ADD, _SUB, _MUL, _DIV, _MOD, _POW, _NEG,
 _LT, _LE, _GT, _GE, _EQ, _NE, _JZ, _JMP) = range(17)
# markers on the operator stack (precedence 0)
_M_LP, _M_Q, _M_C = 20, 21, 22

_BINOPS = {
    '<': (1, _LT), '<=': (1, _LE), '>': (1, _GT), '>=': (1, _GE),
    '==': (1, _EQ), '!=': (1, _NE),
    '+': (2, _ADD), '-': (2, _SUB),
    '*': (3, _MUL), '/': (3, _DIV), '%': (3, _MOD),
    '^': (5, _POW),
}
_NEG_PREC = 4


def _to_int(s):
    # Avoids Python's int<->str digit limit and quadratic conversion.
    n = len(s)
    if n <= 500:
        return int(s)
    half = n // 2
    return _to_int(s[:n - half]) * 10 ** half + _to_int(s[n - half:])


def _syntax_error(kind, text, pos):
    if kind == 5:
        return ("error", pos, "unexpected character '%s'" % text)
    return ("error", pos, "unexpected token '%s'" % text)


def evaluate(src: str, env: dict) -> tuple:
    # ---------- parse: compile to postfix code with jumps ----------
    code = []
    emit = code.append
    ops = []            # entries: (prec, opcode_or_marker, pos_or_code_index)
    expect_operand = True

    def flush():
        # pop operators and finished else-branches down to '(' or '?'
        while ops:
            t = ops[-1]
            if t[0] > 0:
                emit((t[1], None, t[2]))
            elif t[1] == _M_C:
                code[t[2]] = (_JMP, len(code), 0)
            else:
                break
            ops.pop()

    for m in _TOKEN_RE.finditer(src):
        kind = m.lastindex
        if kind == 1:
            continue
        text = m.group()
        pos = m.start()
        if expect_operand:
            if kind == 2:
                emit((_PUSH, _to_int(text), pos))
                expect_operand = False
            elif kind == 3:
                emit((_LOAD, text, pos))
                expect_operand = False
            elif kind == 4 and text == '(':
                ops.append((0, _M_LP, pos))
            elif kind == 4 and text == '-':
                ops.append((_NEG_PREC, _NEG, pos))
            else:
                return _syntax_error(kind, text, pos)
        else:
            if kind != 4:
                return _syntax_error(kind, text, pos)
            b = _BINOPS.get(text)
            if b is not None:
                prec, opc = b
                if prec == 5:
                    pass  # '^' is right-associative and binds tightest
                elif prec == 1:
                    while ops and ops[-1][0] > 1:
                        t = ops.pop()
                        emit((t[1], None, t[2]))
                    if ops and ops[-1][0] == 1:   # non-associative
                        return _syntax_error(kind, text, pos)
                else:
                    while ops and ops[-1][0] >= prec:
                        t = ops.pop()
                        emit((t[1], None, t[2]))
                ops.append((prec, opc, pos))
                expect_operand = True
            elif text == '?':
                while ops and ops[-1][0] > 0:
                    t = ops.pop()
                    emit((t[1], None, t[2]))
                ops.append((0, _M_Q, len(code)))
                emit((_JZ, None, 0))
                expect_operand = True
            elif text == ':':
                flush()
                if not ops or ops[-1][1] != _M_Q:
                    return _syntax_error(kind, text, pos)
                q = ops.pop()
                j = len(code)
                emit((_JMP, None, 0))
                code[q[2]] = (_JZ, len(code), 0)
                ops.append((0, _M_C, j))
                expect_operand = True
            elif text == ')':
                flush()
                if not ops or ops[-1][1] != _M_LP:
                    return _syntax_error(kind, text, pos)
                ops.pop()
            else:  # '(' after an operand
                return _syntax_error(kind, text, pos)

    if expect_operand:
        return ("error", len(src), "unexpected end of input")
    flush()
    if ops:
        return ("error", len(src), "unexpected end of input")

    # ---------- evaluate ----------
    stack = []
    push = stack.append
    pop = stack.pop
    pc = 0
    n = len(code)
    while pc < n:
        op, arg, pos = code[pc]
        pc += 1
        if op == _PUSH:
            push(arg)
        elif op == _LOAD:
            if arg in env:
                push(env[arg])
            else:
                return ("error", pos, "unknown name '%s'" % arg)
        elif op == _ADD:
            b = pop()
            stack[-1] = stack[-1] + b
        elif op == _SUB:
            b = pop()
            stack[-1] = stack[-1] - b
        elif op == _MUL:
            b = pop()
            stack[-1] = stack[-1] * b
        elif op == _NEG:
            stack[-1] = -stack[-1]
        elif op == _POW:
            b = pop()
            if b < 0:
                return ("error", pos, "negative exponent")
            if b > 256:
                return ("error", pos, "exponent too large")
            stack[-1] = stack[-1] ** b
        elif op == _DIV:
            b = pop()
            if b == 0:
                return ("error", pos, "division by zero")
            stack[-1] = stack[-1] // b
        elif op == _MOD:
            b = pop()
            if b == 0:
                return ("error", pos, "division by zero")
            stack[-1] = stack[-1] % b
        elif op == _JZ:
            if pop() == 0:
                pc = arg
        elif op == _JMP:
            pc = arg
        elif op == _LT:
            b = pop()
            stack[-1] = 1 if stack[-1] < b else 0
        elif op == _LE:
            b = pop()
            stack[-1] = 1 if stack[-1] <= b else 0
        elif op == _GT:
            b = pop()
            stack[-1] = 1 if stack[-1] > b else 0
        elif op == _GE:
            b = pop()
            stack[-1] = 1 if stack[-1] >= b else 0
        elif op == _EQ:
            b = pop()
            stack[-1] = 1 if stack[-1] == b else 0
        else:  # _NE
            b = pop()
            stack[-1] = 1 if stack[-1] != b else 0
    return ("ok", stack[-1])

import re
from math import gcd

_LITERAL = re.compile(
    r'([+-]?)(?:([0-9]+)(?:\.([0-9]*))?|\.([0-9]+))(?:[eE]([+-]?)([0-9]+))?'
)


def _to_int(s: str) -> int:
    """int() for a string of ASCII digits, immune to the int/str digit limit."""
    if len(s) <= 2000:
        return int(s)
    h = len(s) // 2
    return _to_int(s[:h]) * 10 ** (len(s) - h) + _to_int(s[h:])


def closest_fraction(x: str, max_num: int, max_den: int) -> str:
    if not isinstance(x, str):
        raise ValueError("x must be a string containing a decimal literal")
    m = _LITERAL.fullmatch(x)
    if m is None:
        raise ValueError("invalid decimal literal: %r" % (x,))
    if max_num < 0:
        raise ValueError("max_num must be >= 0")
    if max_den < 1:
        raise ValueError("max_den must be >= 1")

    sign, ipart, frac1, frac2, esign, edigits = m.groups()
    neg = sign == '-'
    frac = frac1 if frac1 is not None else (frac2 or '')
    digits = ((ipart or '') + frac).lstrip('0')

    N, D = max_num, max_den

    def fmt(a: int, b: int) -> str:
        if a == 0:
            return "0/1"
        return "%s%d/%d" % ("-" if neg else "", a, b)

    if not digits or N == 0:          # x == 0, or only 0/1 is available
        return "0/1"

    exp = 0
    if edigits is not None:
        exp = _to_int(edigits.lstrip('0') or '0')
        if esign == '-':
            exp = -exp
    e = exp - len(frac)               # |x| = mant * 10**e
    L = len(digits)                   # 10**(L-1+e) <= |x| < 10**(L+e)

    # Cheap shortcuts (also keep 10**|e| small for extreme exponents).
    if L - 1 + e >= N.bit_length():           # |x| >= 10**t >= 2**t > N
        return fmt(N, 1)
    if L + e <= -(D.bit_length() + 1):        # |x| < 1/(2*D): zero is closest
        return "0/1"

    mant = _to_int(digits)
    if e >= 0:
        p, q = mant * 10 ** e, 1
    else:
        p, q = mant, 10 ** (-e)
    g = gcd(p, q)
    p //= g
    q //= g                           # |x| = p/q exactly, in lowest terms, > 0

    if p <= N and q <= D:             # x itself is representable
        return fmt(p, q)
    if p >= N * q:                    # |x| >= N: the largest candidate is N/1
        return fmt(N, 1)

    # Stern-Brocot walk with run-length steps.
    # Invariant: a/b < p/q < c/d, b*c - a*d == 1, a/b in the candidate set,
    # c/d in the candidate set or still 1/0.
    a, b, c, d = 0, 1, 1, 0
    while True:
        moved = False

        # Move the lower bound up: a/b -> (a + k*c)/(b + k*d), staying below x.
        r = p * b - a * q             # > 0
        s = c * q - p * d             # > 0
        k = min(r // s, (N - a) // c)
        if d:
            k = min(k, (D - b) // d)
        if k > 0:
            a += k * c
            b += k * d
            moved = True

        # Move the upper bound down: c/d -> (c + k*a)/(d + k*b), staying above x.
        r = p * b - a * q
        s = c * q - p * d
        k = min(s // r, (D - d) // b)
        if a:
            k = min(k, (N - c) // a)
        if k > 0:
            c += k * a
            d += k * b
            moved = True

        if not moved:
            break

    # a/b and c/d are now the neighbours of |x| in the candidate set.
    r = p * b - a * q                 # (x - a/b) = r / (q*b)
    s = c * q - p * d                 # (c/d - x) = s / (q*d)
    lo_cmp = r * d
    hi_cmp = s * b
    if lo_cmp < hi_cmp:
        return fmt(a, b)
    if lo_cmp > hi_cmp:
        return fmt(c, d)
    # Tie: smaller denominator, then the one closer to zero (the lower one).
    if d < b:
        return fmt(c, d)
    return fmt(a, b)

from bisect import bisect_left, bisect_right


def run_ops(ops: list[tuple]) -> list:
    # Offline coordinate compression of every start a valid booking could have.
    xs = sorted({op[1] for op in ops if op[0] == "book" and op[1] < op[2]})
    n = len(xs)
    idx = {x: i for i, x in enumerate(xs)}

    size = 1
    while size < n:
        size <<= 1

    INF = 1 << 62
    # Max segment tree over compressed starts.
    # Leaf value: -1 if no booking starts there, otherwise the free gap
    # between this booking's end and the next booking's start (INF if last).
    tree = [-1] * (2 * size)
    end = [0] * max(n, 1)          # end[i] valid only while the booking is present
    fen = [0] * (n + 1)            # Fenwick tree of booking lengths

    def update(i, v):
        i += size
        tree[i] = v
        i >>= 1
        while i:
            a = tree[2 * i]
            b = tree[2 * i + 1]
            tree[i] = a if a >= b else b
            i >>= 1

    def find_first(l, d):
        """Smallest index >= l whose value >= d, or -1."""
        if l >= size:
            return -1
        i = l + size
        while True:
            if tree[i] >= d:
                while i < size:
                    i <<= 1
                    if tree[i] < d:
                        i += 1
                return i - size
            while i & 1:
                i >>= 1
            if i == 0:
                return -1
            i += 1

    def find_last(r, d):
        """Largest index <= r whose value >= d, or -1."""
        if r < 0:
            return -1
        if r >= size:
            r = size - 1
        i = r + size
        while True:
            if tree[i] >= d:
                while i < size:
                    i = 2 * i + 1
                    if tree[i] < d:
                        i -= 1
                return i - size
            while not (i & 1):
                i >>= 1
            if i == 1:
                return -1
            i -= 1

    def fen_add(i, v):
        i += 1
        while i <= n:
            fen[i] += v
            i += i & (-i)

    def fen_prefix(i):
        """Sum of lengths for compressed indices 0..i."""
        i += 1
        s = 0
        while i > 0:
            s += fen[i]
            i -= i & (-i)
        return s

    def occupied_before(x):
        """Number of occupied integer times strictly less than x."""
        pos = bisect_left(xs, x) - 1
        if pos < 0:
            return 0
        total = fen_prefix(pos)
        p = find_last(pos, 0)
        if p != -1 and end[p] > x:
            total -= end[p] - x      # only the last such booking can overhang
        return total

    out = []
    for op in ops:
        kind = op[0]

        if kind == "book":
            s, e = op[1], op[2]
            if s >= e:
                out.append("INVALID")
                continue
            i = idx[s]
            p = find_last(i, 0)                  # booking with largest start <= s
            if p != -1 and end[p] > s:
                out.append("CONFLICT")
                continue
            nx = find_first(i, 0)                # booking with smallest start > s
            if nx != -1 and xs[nx] < e:
                out.append("CONFLICT")
                continue
            end[i] = e
            update(i, (xs[nx] - e) if nx != -1 else INF)
            if p != -1:
                update(p, s - end[p])
            fen_add(i, e - s)
            out.append(True)

        elif kind == "cancel":
            s = op[1]
            i = idx.get(s)
            if i is None or tree[size + i] < 0:
                out.append(0)
                continue
            length = end[i] - s
            update(i, -1)
            p = find_last(i - 1, 0)
            if p != -1:
                nx = find_first(i + 1, 0)
                update(p, (xs[nx] - end[p]) if nx != -1 else INF)
            fen_add(i, -length)
            out.append(length)

        elif kind == "first_fit":
            t, d = op[1], op[2]
            pos = bisect_right(xs, t) - 1
            p = find_last(pos, 0)                # booking with largest start <= t
            if p != -1:
                ep = end[p]
                if ep > t:
                    # t is inside booking p: first booking from p on with a big enough gap
                    j = find_first(p, d)
                    out.append(end[j])
                else:
                    g = tree[size + p]
                    if g >= INF or g - (t - ep) >= d:
                        out.append(t)
                    else:
                        j = find_first(p + 1, d)
                        out.append(end[j])
            else:
                nx = find_first(0, 0)            # earliest booking, if any
                if nx == -1 or xs[nx] - t >= d:
                    out.append(t)
                else:
                    j = find_first(nx, d)
                    out.append(end[j])

        elif kind == "free_between":
            a, b = op[1], op[2]
            if a >= b:
                out.append(0)
            else:
                out.append((b - a) - (occupied_before(b) - occupied_before(a)))

        else:
            raise ValueError("unknown operation: %r" % (kind,))

    return out

import heapq
from collections import defaultdict


def window_medians(readings, k):
    if not isinstance(k, int) or k < 1:
        raise ValueError("k must be a positive int")

    low = []    # max-heap via negation: the smaller half, its top is the median
    high = []   # min-heap: the larger half
    delayed = defaultdict(int)  # value -> pending lazy deletions
    sizes = {"low": 0, "high": 0}  # live (not yet deleted) element counts
    out = []

    # Invariant between operations: the top of each heap (if any) is live.

    def prune(heap, sign):
        # drop deleted values sitting on top of a heap
        while heap:
            v = sign * heap[0]
            if delayed.get(v, 0) > 0:
                if delayed[v] == 1:
                    del delayed[v]
                else:
                    delayed[v] -= 1
                heapq.heappop(heap)
            else:
                break

    def rebalance():
        # invariant: sizes["low"] == sizes["high"] or sizes["low"] == sizes["high"] + 1
        if sizes["low"] > sizes["high"] + 1:
            heapq.heappush(high, -heapq.heappop(low))
            sizes["low"] -= 1
            sizes["high"] += 1
            prune(low, -1)
        elif sizes["low"] < sizes["high"]:
            heapq.heappush(low, -heapq.heappop(high))
            sizes["high"] -= 1
            sizes["low"] += 1
            prune(high, 1)          # fix: a deleted value may now be on top of high

    def add(x):
        if not low or x <= -low[0]:
            heapq.heappush(low, -x)
            sizes["low"] += 1
        else:
            heapq.heappush(high, x)
            sizes["high"] += 1
        rebalance()

    def remove(x):
        delayed[x] += 1
        if x <= -low[0]:            # fix: was '<', equal values belong to low
            sizes["low"] -= 1
            if x == -low[0]:
                prune(low, -1)
        else:
            sizes["high"] -= 1
            if x == high[0]:
                prune(high, 1)
        rebalance()

    for i, x in enumerate(readings):
        if x is not None:
            add(x)
        # fix: evict the tick leaving the window even when the current reading is None
        if i >= k:
            old = readings[i - k]
            if old is not None:
                remove(old)
        out.append(-low[0] if sizes["low"] else None)
    return out

TWO_CHAR_OPS = ("==", "!=", "<=", ">=", "->")
ONE_CHAR_OPS = "<>=+-*/(),"
ESCAPES = {'"': '"', "\\": "\\", "n": "\n", "t": "\t"}


def _is_digit(ch):
    return "0" <= ch <= "9"


def _is_ident_start(ch):
    return ch == "_" or "a" <= ch <= "z" or "A" <= ch <= "Z"


def _is_ident_char(ch):
    return _is_ident_start(ch) or _is_digit(ch)


def tokenize(src):
    tokens = []
    n = len(src)
    i, line, col = 0, 1, 1

    def fail(at_line, at_col, message):
        raise ValueError("line %d col %d: %s" % (at_line, at_col, message))

    while i < n:
        ch = src[i]

        if ch == "\n":
            i += 1
            line += 1
            col = 1
            continue
        if ch == " " or ch == "\t":
            i += 1
            col += 1
            continue
        if ch == "#":
            # Comment runs up to, but not including, the newline; the newline
            # branch above then updates line/col.
            end = src.find("\n", i)
            i = n if end == -1 else end
            continue

        if _is_digit(ch):
            j = i
            while j < n and _is_digit(src[j]):
                j += 1
            is_float = False
            # FRACTION: "." followed by at least one digit.
            if j + 1 < n and src[j] == "." and _is_digit(src[j + 1]):
                j += 2
                while j < n and _is_digit(src[j]):
                    j += 1
                is_float = True
            # EXPONENT: e/E, optional sign, at least one digit.
            if j < n and src[j] in ("e", "E"):
                k = j + 1
                if k < n and src[k] in ("+", "-"):
                    k += 1
                if k < n and _is_digit(src[k]):
                    while k < n and _is_digit(src[k]):
                        k += 1
                    j = k
                    is_float = True
            text = src[i:j]
            tokens.append(("NUMBER", float(text) if is_float else int(text), line, col))
            col += j - i
            i = j
            continue

        if _is_ident_start(ch):
            j = i
            while j < n and _is_ident_char(src[j]):
                j += 1
            tokens.append(("IDENT", src[i:j], line, col))
            col += j - i
            i = j
            continue

        if ch == '"':
            j = i + 1
            chars = []
            while True:
                if j >= n or src[j] == "\n":
                    fail(line, col, "unterminated string")
                c = src[j]
                if c == '"':
                    j += 1
                    break
                if c == "\\":
                    if j + 1 >= n or src[j + 1] == "\n":
                        fail(line, col, "unterminated string")
                    if src[j + 1] not in ESCAPES:
                        fail(line, col + (j - i), "bad escape")
                    chars.append(ESCAPES[src[j + 1]])
                    j += 2
                    continue
                chars.append(c)
                j += 1
            tokens.append(("STRING", "".join(chars), line, col))
            col += j - i
            i = j
            continue

        if src[i:i + 2] in TWO_CHAR_OPS:
            tokens.append(("OP", src[i:i + 2], line, col))
            i += 2
            col += 2
            continue
        if ch in ONE_CHAR_OPS:
            tokens.append(("OP", ch, line, col))
            i += 1
            col += 1
            continue

        fail(line, col, "unexpected character %r" % ch)

    return tokens
